export const uid=()=>Math.random().toString(36).slice(2,10);
export const localDay=(time=Date.now())=>{const d=new Date(time);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
export const now=s=>Date.now()+(s.timeOffset||0);
export function initial(){return {version:1,day:localDay(),timeOffset:0,screen:'welcome',onboarded:false,profile:{name:'',phone:''},tone:'balanced',answers:[],goals:[],tasks:[],templates:[],requestedBreaks:2,ledger:{},activeUntil:0,selectedApps:['Instagram','TikTok','YouTube'],calendar:false,tutorial:false,messages:[],suggestions:[],codeExpires:0};}
export function stats(s){const total=s.tasks.length,done=s.tasks.filter(t=>t.done).length,remaining=total-done,effective=Math.min(s.requestedBreaks,total);const milestones=Array.from({length:effective},(_,i)=>({id:i+1,at:Math.ceil((i+1)*total/(effective+1))}));return {total,done,remaining,effective,percent:total?Math.round(done/total*100):0,milestones,banked:Object.values(s.ledger).filter(x=>!x.used).length,active:s.activeUntil>now(s)&&remaining>0,blocked:remaining>0&&s.activeUntil<=now(s)&&s.selectedApps.length>0,next:milestones.find(x=>!s.ledger[x.id]&&x.at<total)};}
export function reconcile(s){if(s.activeUntil<=now(s))s.activeUntil=0;const st=stats(s);if(!st.remaining){s.activeUntil=0;return [];}const earned=[];for(const m of st.milestones){if(st.done>=m.at&&!s.ledger[m.id]){s.ledger[m.id]={id:m.id,used:false};earned.push(m.id);}}return earned;}
export function addTask(s,data){const title=String(data.title||'').trim();if(!title)throw Error('Give your task a name. A few words are enough.');const t={id:uid(),title,duration:data.duration||'',recurrence:data.recurrence||'none',photo:!!data.photo,goalId:data.goalId||'',done:false,failures:0,anchor:s.day};s.tasks.push(t);if(t.recurrence!=='none')s.templates.push({...t});reconcile(s);return t;}
export function editTask(s,id,data){const t=s.tasks.find(t=>t.id===id);if(!t)throw Error('Task not found.');const title=String(data.title||'').trim();if(!title)throw Error('Give your task a name. A few words are enough.');if(t.recurrence!==(data.recurrence||'none'))t.anchor=s.day;Object.assign(t,{title,duration:data.duration||'',recurrence:data.recurrence||'none',photo:!!data.photo,goalId:data.goalId||''});s.templates=s.templates.filter(x=>x.id!==id);if(t.recurrence!=='none')s.templates.push({...t});reconcile(s);return t;}
export function removeTask(s,id){s.tasks=s.tasks.filter(t=>t.id!==id);s.templates=s.templates.filter(t=>t.id!==id);reconcile(s);}
export function completeTask(s,id){const t=s.tasks.find(t=>t.id===id);if(!t)return [];t.done=true;return reconcile(s);}
export function photoAttempt(s,id,confidence){const t=s.tasks.find(t=>t.id===id);if(!t)throw Error('Task not found.');if(confidence>=.8){completeTask(s,id);return 'verified';}t.failures++;if(t.failures>=3){completeTask(s,id);return 'supported';}return 'retry';}
export function startBreak(s){reconcile(s);if(!stats(s).remaining)throw Error('Your apps are already fully unlocked.');if(stats(s).active)throw Error('Your break is already running.');const reward=Object.values(s.ledger).find(x=>!x.used);if(!reward)throw Error('Keep going — your next break is coming.');reward.used=true;s.activeUntil=now(s)+600000;return s.activeUntil;}
export function scheduled(template,day){const d=new Date(day+'T12:00:00'),a=new Date(template.anchor+'T12:00:00');if(d<a)return false;if(template.recurrence==='daily')return true;if(template.recurrence==='weekly')return d.getDay()===a.getDay();if(template.recurrence==='monthly'){const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();return d.getDate()===Math.min(a.getDate(),last);}return false;}
export function rollover(s){const day=localDay(now(s));if(day===s.day)return false;s.day=day;s.tasks=s.tasks.filter(t=>!t.done&&t.recurrence==='none');for(const template of s.templates){if(scheduled(template,day))s.tasks.push({...template,done:false,failures:0});}s.ledger={};s.activeUntil=0;return true;}
export function deleteGoal(s,id){s.goals=s.goals.filter(g=>g.id!==id);for(const t of [...s.tasks,...s.templates])if(t.goalId===id)t.goalId='';}
export function suggest(s,goal=s.goals[0]){const title=goal?.title||'Make time for what matters',id=goal?.id||'';let list;if(/final|exam|class|grade|stud|course/i.test(title))list=[['Pick the hardest topic to review',10,'Make the big goal less overwhelming.'],['Review one set of class notes',20,'Build a little confidence before your next class.'],['Try five practice questions',15,'Find out what is sticking.'],['Make a plan for tomorrow’s study session',5,'Make your next start easier.']];else if(/run|fit|gym|health|walk/i.test(title))list=[['Lay out your workout clothes',5,'Remove one small barrier to starting.'],['Get outside for a short walk',15,'Build consistency at your own pace.'],['Plan your next workout',10,'Choose a manageable next step.'],['Refill your water bottle',2,'Set yourself up to feel good.']];else list=[[`Choose one next step for “${title}”`,5,'Decide where a small start would help.'],['Spend 15 minutes on that first step',15,'Create momentum without a big commitment.'],['Gather what you need to continue',10,'Give your future self an easier start.'],['Plan your next small step',5,'Keep your goal moving tomorrow.']];return list.map(([title,duration,why])=>({id:uid(),title,duration,why,goalId:id,recurrence:'none',photo:false,selected:true}));}
